import type { Locale } from 'date-fns';
import { bg } from 'date-fns/locale/bg';
import { cs } from 'date-fns/locale/cs';
import { hu } from 'date-fns/locale/hu';
import { it } from 'date-fns/locale/it';
import { ja } from 'date-fns/locale/ja';
import { ko } from 'date-fns/locale/ko';
import { nl } from 'date-fns/locale/nl';
import { pl } from 'date-fns/locale/pl';
import { pt } from 'date-fns/locale/pt';
import { ptBR } from 'date-fns/locale/pt-BR';
import { ro } from 'date-fns/locale/ro';
import { sk } from 'date-fns/locale/sk';
import { sl } from 'date-fns/locale/sl';
import { sv } from 'date-fns/locale/sv';
import { th } from 'date-fns/locale/th';
import { tr } from 'date-fns/locale/tr';
import { vi } from 'date-fns/locale/vi';
import { zhCN } from 'date-fns/locale/zh-CN';
import { setLoadedDateLocale } from './dateLocaleState';

// Relative dates ("3 months ago") come from date-fns, which needs a locale
// object per language. Only de, fr, es and en-US were wired up, so every other
// UI language fell back to German. All of them live in this one lazy chunk: a
// chunk per language would each add an entry to the preload map in the boot
// chunk, which NOVA's boot budget cannot afford. Keys are the Tolgee language
// codes. de, en, es and fr are not here on purpose: src/boot/timeago.ts imports
// them statically, and a second, dynamic import would split each into its own
// chunk named like the language dictionary (de.<hash>.js), which the login
// first-render check reads as a second dictionary download.
const LOCALES: Record<string, Locale> = {
  bg: bg,
  cs: cs,
  hu: hu,
  'hu-hu': hu,
  it: it,
  ja: ja,
  ko: ko,
  'ko-kr': ko,
  nl: nl,
  pl: pl,
  pt: pt,
  'pt-br': ptBR,
  ro: ro,
  sk: sk,
  sl: sl,
  sv: sv,
  th: th,
  tr: tr,
  vi: vi,
  zh: zhCN,
};

/** Set the date-fns locale of a UI language. Resolves false when there is none. */
export async function applyDateLocale(language: string): Promise<boolean> {
  const locale = LOCALES[String(language || '').toLowerCase()];
  if (!locale) return false;
  setLoadedDateLocale(locale);
  return true;
}
